function formatDate(d) {
    let jaar = d.getFullYear();
    let maand = String(d.getMonth() + 1).padStart(2, '0');
    let dag = String(d.getDate()).padStart(2, '0');
    return `${jaar}-${maand}-${dag}`;
}

let vandaag = new Date();
let morgen = new Date();
morgen.setDate(vandaag.getDate() + 1);

let startStr = formatDate(vandaag);
let endStr = formatDate(morgen);

msg.url = `https://api.energy-charts.info/price?bzn=BE&start=${startStr}&end=${endStr}`;
return msg;

let tijden = msg.payload.unix_seconds;
let prijzen = msg.payload.price;

// Sla API-status op voor het Watchdog tabblad
global.set("epex_api_deprecated", msg.payload.deprecated === true);

if (!tijden || !prijzen || tijden.length === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "Geen data ontvangen" });
    return null;
}

let points = [];
for (let i = 0; i < tijden.length; i++) {
    let prijsGetal = parseFloat(prijzen[i]);
    if (isNaN(prijsGetal)) continue;

    points.push({
        measurement: "epex_kwartier",
        fields: { prijs: prijsGetal },
        tags: { type: "epex" },
        timestamp: new Date(tijden[i] * 1000)
    });
}

node.status({ fill: "green", shape: "dot", text: `${points.length} kwartieren opgeslagen` });
msg.payload = points;
return msg;

let records = msg.payload.results;
if (!records || records.length === 0) return null;

let points = [];
for (let i = 0; i < records.length; i++) {
    let item = records[i];
    if (item.imbalanceprice === null || item.imbalanceprice === undefined || !item.datetime) continue;

    let prijsGetal = parseFloat(item.imbalanceprice);
    if (isNaN(prijsGetal)) continue;

    points.push({
        measurement: "onbalans_kwartier",
        fields: { prijs: prijsGetal },
        tags: { type: "onbalans" },
        timestamp: new Date(item.datetime)
    });
}

node.status({ fill: "green", shape: "dot", text: `${points.length} kwartieren opgeslagen` });
msg.payload = points;
return msg;

let records = msg.payload.results;
if (!records || records.length === 0) return null;

let points = [];
for (let i = 0; i < records.length; i++) {
    let item = records[i];
    if (item.imbalanceprice === null || item.imbalanceprice === undefined || !item.datetime) continue;

    let prijsGetal = parseFloat(item.imbalanceprice);
    if (isNaN(prijsGetal)) continue;

    points.push({
        measurement: "onbalans_minuut",
        fields: { prijs: prijsGetal },
        tags: { type: "onbalans" },
        timestamp: new Date(item.datetime)
    });
}

node.status({ fill: "green", shape: "dot", text: `${points.length} minuten opgeslagen` });
msg.payload = points;
return msg;

let morgen = new Date();
morgen.setDate(morgen.getDate() + 1);

let jaar = morgen.getFullYear();
let maand = String(morgen.getMonth() + 1).padStart(2, '0');
let dag = String(morgen.getDate()).padStart(2, '0');

let datumISO = `${jaar}-${maand}-${dag}`;
let datumWeergave = `${dag}-${maand}-${jaar}`;

if (msg.force === true) {
    flow.set("epexLaatstGestuurd", "");
}

// Als we vandaag al voor morgen gestuurd hebben, hoeven we InfluxDB niet eens te vragen
if (flow.get("epexLaatstGestuurd") === datumWeergave) {
    node.status({ fill: "green", shape: "ring", text: `Al verstuurd voor ${datumWeergave}` });
    return null;
}

let start = new Date(`${datumISO}T00:00:00`).toISOString();
let end = new Date(`${datumISO}T23:59:59.999`).toISOString();

let q = `SELECT "prijs" FROM "epex_kwartier" WHERE time >= '${start}' AND time <= '${end}' ORDER BY time ASC`;
msg.url = "http://epex_influxdb:8086/query?db=energie_db&epoch=ms&q=" + encodeURIComponent(q);
msg.headers = { "Authorization": "Token epex_super_secret_token_2026" };
msg.datumWeergave = datumWeergave;
return msg;

let res = msg.payload.results;
if (!res || !res[0] || !res[0].series) {
    node.status({ fill: "yellow", shape: "ring", text: "Morgen nog niet in DB" });
    return null;
}

let rows = res[0].series[0].values; // [ [timestamp_ms, prijs], ... ]
if (rows.length < 90) {
    node.status({ fill: "yellow", shape: "ring", text: `Pas ${rows.length} kwartieren binnen` });
    return null;
}

let timestampsMs = rows.map(r => r[0]);
let prijzen = rows.map(r => r[1]);

let indices25 = [];
let indices0 = [];
let minPrijs = Math.min(...prijzen);
let minTijdIndex = prijzen.indexOf(minPrijs);
let minTijdstip = "";

function formatLocalHHmm(ms) {
    let d = new Date(ms);
    return d.getHours().toString().padStart(2, '0') + ":" + d.getMinutes().toString().padStart(2, '0');
}

for (let i = 0; i < timestampsMs.length; i++) {
    if (i === minTijdIndex) {
        minTijdstip = formatLocalHHmm(timestampsMs[i]);
    }
    if (prijzen[i] <= 25) indices25.push(i);
    if (prijzen[i] <= 0) indices0.push(i);
}

function maakTijdBlokken(indices) {
    let resultaat = [];
    if (indices.length === 0) return resultaat;
    let startIdx = indices[0];
    for (let i = 0; i < indices.length; i++) {
        if (indices[i + 1] !== indices[i] + 1) {
            let s = formatLocalHHmm(timestampsMs[startIdx]);
            let e = formatLocalHHmm(timestampsMs[indices[i]] + 15 * 60000);
            resultaat.push(`⏱️ <b>${s} tot ${e}</b>`);
            startIdx = indices[i + 1];
        }
    }
    return resultaat;
}

let blokken25 = maakTijdBlokken(indices25);
let blokken0 = maakTijdBlokken(indices0);
let datumMorgen = msg.datumWeergave;

let berichtTekst = `📊 <b>EPEX PRIJZEN VOOR ${datumMorgen}</b>\n\n`;

if (blokken25.length > 0) {
    berichtTekst += `✅ <b>Momenten onder de € 25:</b>\n${blokken25.join("\n")}\n\n`;
} else {
    berichtTekst += `❌ <b>Er zijn geen lage waardes onder de € 25.</b>\n\n`;
}

if (blokken0.length > 0) {
    berichtTekst += `✅ <b>Momenten onder de € 0:</b>\n${blokken0.join("\n")}\n\n`;
}

berichtTekst += `📉 <b>Laagste prijs: € ${minPrijs.toFixed(2)} / MWh</b>\n`;
berichtTekst += `⏱️ <b>${minTijdstip}</b>`;

flow.set("epexLaatstGestuurd", datumMorgen);
node.status({ fill: "green", shape: "dot", text: `Verstuurd voor ${datumMorgen}` });

let idsRaw = env.get("TELEGRAM_CHAT_ID") || "";
let chatIds = idsRaw.split(",").map(id => id.trim()).filter(id => id.length > 0);

chatIds.forEach(id => {
    node.send({
        payload: {
            chatId: id,
            type: "message",
            content: berichtTekst,
            options: { parse_mode: "HTML" }
        }
    });
});

return null;

let nu = new Date();
let kwartier = Math.floor(nu.getMinutes() / 15) * 15;

let startTijd = new Date(nu);
startTijd.setMinutes(kwartier, 0, 0);
let eindTijd = new Date(startTijd.getTime() + 15 * 60000);

let q = `SELECT "prijs" FROM "epex_kwartier" WHERE time = ${startTijd.getTime()}ms OR time = ${eindTijd.getTime()}ms ORDER BY time ASC`;
msg.url = "http://epex_influxdb:8086/query?db=energie_db&epoch=ms&q=" + encodeURIComponent(q);
msg.headers = { "Authorization": "Token epex_super_secret_token_2026" };
return msg;

let res = msg.payload.results;
if (!res || !res[0] || !res[0].series) return null;

let waarden = res[0].series[0].values;
if (waarden.length < 2) return null;

let prijsNu = waarden[0][1];
let prijsStraks = waarden[1][1];
let tijdStraksMs = waarden[1][0];
let drempel = 25;

let d = new Date(tijdStraksMs);
let weergaveTijd = d.getHours().toString().padStart(2, '0') + ":" + d.getMinutes().toString().padStart(2, '0');

node.status({ fill: "blue", shape: "ring", text: `Nu: €${prijsNu} -> ${weergaveTijd}: €${prijsStraks}` });

if (prijsNu > drempel && prijsStraks <= drempel) {
    let bericht = `🔔 <b>PRIJS ALARM!</b>\n\nOver 15 minuten (om <b>${weergaveTijd}</b>) zakt de prijs onder de € ${drempel}!\n\n💰 Prijs: € ${prijsStraks.toFixed(2)} / MWh\n⚡ <i>Tijd om de grote verbruikers aan te zetten!</i>`;

    let idsRaw = env.get("TELEGRAM_CHAT_ID") || "";
    let chatIds = idsRaw.split(",").map(id => id.trim()).filter(id => id.length > 0);

    chatIds.forEach(id => {
        node.send({
            payload: {
                chatId: id,
                type: "message",
                content: bericht,
                options: { parse_mode: "HTML" }
            }
        });
    });
}
return null;

let nu = new Date();
let vandaag = new Date(nu.getFullYear(), nu.getMonth(), nu.getDate());
let gisteren = new Date(vandaag.getTime() - 24 * 60 * 60 * 1000);

let startStr = gisteren.toISOString();
let eindStr = vandaag.toISOString();

let qMin = `SELECT "prijs" FROM "onbalans_minuut" WHERE time >= '${startStr}' AND time < '${eindStr}' ORDER BY time ASC`;
let qQOnb = `SELECT "prijs" FROM "onbalans_kwartier" WHERE time >= '${startStr}' AND time < '${eindStr}' ORDER BY time ASC`;
let qQEpex = `SELECT "prijs" FROM "epex_kwartier" WHERE time >= '${startStr}' AND time < '${eindStr}' ORDER BY time ASC`;

msg.url = "http://epex_influxdb:8086/query?db=energie_db&epoch=ms&q=" + encodeURIComponent(`${qMin};${qQOnb};${qQEpex}`);
msg.headers = { "Authorization": "Token epex_super_secret_token_2026" };
msg.startMs = gisteren.getTime();
msg.datumWeergave = gisteren.toLocaleDateString('nl-BE');
return msg;

let results = msg.payload.results;
if (!results || results.length < 3) return null;

let startMs = msg.startMs;
let datum = msg.datumWeergave;

let actualMin = new Set();
let actualQOnb = new Set();
let actualQEpex = new Set();

if (results[0] && results[0].series) results[0].series[0].values.forEach(v => actualMin.add(v[0]));
if (results[1] && results[1].series) results[1].series[0].values.forEach(v => actualQOnb.add(v[0]));
if (results[2] && results[2].series) results[2].series[0].values.forEach(v => actualQEpex.add(v[0]));

let missingMin = [];
let missingQOnb = [];
let missingQEpex = [];

function formatTijd(tms) {
    let d = new Date(tms);
    return d.getHours().toString().padStart(2, '0') + ":" + d.getMinutes().toString().padStart(2, '0');
}

for (let i = 0; i < 1440; i++) {
    let t = startMs + i * 60 * 1000;
    if (!actualMin.has(t)) missingMin.push(formatTijd(t));
}

for (let i = 0; i < 96; i++) {
    let t = startMs + i * 15 * 60 * 1000;
    let tStr = formatTijd(t);
    if (!actualQOnb.has(t)) missingQOnb.push(tStr);
    if (!actualQEpex.has(t)) missingQEpex.push(tStr);
}

let isDeprecated = global.get("epex_api_deprecated") === true;

if (missingMin.length > 0 || missingQOnb.length > 0 || missingQEpex.length > 0 || isDeprecated) {
    let bericht = `⚠️ <b>WATCHDOG RAPPORT (${datum})</b>\n\n`;

    if (isDeprecated) {
        bericht += `🚨 <b>LET OP:</b> Energy-Charts API heeft gemeld dat deze versie binnenkort stopt (deprecated)!\n\n`;
    }
    if (missingQEpex.length > 0) {
        bericht += `❌ <b>EPEX Kwartier (${96 - missingQEpex.length}/96):</b>\n└ Gemist: ${missingQEpex.slice(0, 12).join(', ')}${missingQEpex.length > 12 ? '...' : ''}\n\n`;
    }
    if (missingQOnb.length > 0) {
        bericht += `❌ <b>Onbalans Kwartier (${96 - missingQOnb.length}/96):</b>\n└ Gemist: ${missingQOnb.slice(0, 12).join(', ')}${missingQOnb.length > 12 ? '...' : ''}\n\n`;
    }
    if (missingMin.length > 0) {
        bericht += `❌ <b>Onbalans Minuut (${1440 - missingMin.length}/1440):</b>\n`;
        bericht += missingMin.length > 15 ? `└ Totaal ${missingMin.length} min gemist (o.a. ${missingMin.slice(0, 8).join(', ')}...)\n` : `└ Gemist: ${missingMin.join(', ')}\n`;
    }

    node.status({ fill: "red", shape: "dot", text: `Gaten gevonden op ${datum}` });
    let targetChat = env.get("TELEGRAM_ADMIN_ID") || (env.get("TELEGRAM_CHAT_ID") || "").split(",")[0].trim();
    msg.payload = {
        chatId: targetChat,
        type: "message",
        content: bericht,
        options: { parse_mode: "HTML" }
    };
    return msg;
}

node.status({ fill: "green", shape: "dot", text: `${datum}: 100% compleet!` });
return null;

// We zoeken de gebruiker op basis van naam EN wachtwoord
msg.topic = "SELECT id, gebruikersnaam, rol, telegram_chat_id FROM gebruikers WHERE gebruikersnaam = ? AND wachtwoord_hash = ?";
msg.payload = [msg.payload.username, msg.payload.password];
return msg;

if (msg.payload && msg.payload.length > 0) {
    // Gebruiker gevonden!
    msg.payload = { success: true, user: msg.payload[0] };
} else {
    // Niet gevonden of fout wachtwoord
    msg.payload = { success: false, error: "Verkeerde gebruikersnaam of wachtwoord!" };
}
return msg;

// Nieuwe gebruiker aanmaken. We geven standaard de rol 'user'
msg.topic = "INSERT INTO gebruikers (gebruikersnaam, email, wachtwoord_hash, rol) VALUES (?, ?, ?, 'user')";
msg.payload = [msg.payload.username, msg.payload.email, msg.payload.password];
return msg;

if (msg.payload && msg.payload.insertId) {
    // insertId betekent dat de database succesvol een nieuwe rij (ID) heeft aangemaakt
    msg.payload = { success: true };
} else {
    msg.payload = { success: false, error: "Kon gebruiker niet aanmaken." };
}
return msg;

let errorMsg = "Er is een fout opgetreden bij het registreren.";

// Check of de foutmelding van MariaDB komt omdat de naam of email al bestaat (UNIQUE restrictie)
if (msg.error && msg.error.message.includes("ER_DUP_ENTRY")) {
    errorMsg = "Deze gebruikersnaam of dit e-mailadres is al in gebruik!";
}

msg.payload = { success: false, error: errorMsg };
return msg;

// 1. Haal de datum op uit query, payload of rechtstreeks uit de URL
let datum = null;
if (msg.req && msg.req.query && msg.req.query.datum) {
    datum = msg.req.query.datum;
} else if (msg.req && msg.req.url && msg.req.url.includes("datum=")) {
    let match = msg.req.url.match(/datum=([0-9]{4}-[0-9]{2}-[0-9]{2})/);
    if (match) datum = match[1];
} else if (msg.payload && msg.payload.datum) {
    datum = msg.payload.datum;
}

if (!datum) {
    datum = new Date().toISOString().split('T')[0];
}

// Laat onder het blokje in Node-RED zien welke datum binnenkomt!
node.status({ fill: "green", shape: "dot", text: "Datum: " + datum });

// 2. Haal iets ruimer op (-2 uur tot +2 uur rondom de UTC dag) zodat tijdzone Zomer/Wintertijd nooit data mist!
let dStart = new Date(datum + "T00:00:00Z");
dStart.setHours(dStart.getHours() - 3);
let dStop = new Date(datum + "T23:59:59Z");
dStop.setHours(dStop.getHours() + 3);

msg.query = `
  from(bucket: "energie_db")
    |> range(start: ${dStart.toISOString()}, stop: ${dStop.toISOString()})
    |> filter(fn: (r) => r["_measurement"] == "epex_kwartier" or r["_measurement"] == "onbalans_kwartier" or r["_measurement"] == "onbalans_minuut")
    |> filter(fn: (r) => r["_field"] == "prijs")
    |> keep(columns: ["_time", "_measurement", "_value"])
    |> pivot(rowKey:["_time"], columnKey: ["_measurement"], valueColumn: "_value")
    |> sort(columns: ["_time"])
`;

return msg;

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.payload = [];
    return msg;
}

let gevraagdeDatum = null;
if (msg.req && msg.req.query && msg.req.query.datum) {
    gevraagdeDatum = msg.req.query.datum;
} else if (msg.req && msg.req.url && msg.req.url.includes("datum=")) {
    let match = msg.req.url.match(/datum=([0-9]{4}-[0-9]{2}-[0-9]{2})/);
    if (match) gevraagdeDatum = match[1];
}

// Map om de inkomende data te bewaren per minuut (als timestamp)
let dataMapEpex = {};
let dataMapOnb15 = {};
let dataMapOnb1 = {};

msg.payload.forEach(row => {
    if (!row._time) return;
    let d = new Date(row._time);
    let ms = d.getTime();

    if (row.epex_kwartier !== undefined && row.epex_kwartier !== null) {
        dataMapEpex[ms] = Number(row.epex_kwartier);
    }
    if (row.onbalans_kwartier !== undefined && row.onbalans_kwartier !== null) {
        dataMapOnb15[ms] = Number(row.onbalans_kwartier);
    }
    if (row.onbalans_minuut !== undefined && row.onbalans_minuut !== null) {
        dataMapOnb1[ms] = Number(row.onbalans_minuut);
    }
});

let doelDatumStr = gevraagdeDatum || new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Brussels' }).split(' ')[0];
let startDagMs = new Date(doelDatumStr + "T00:00:00").getTime();

let resultaat = [];

// Loop over alle 96 kwartieren in een dag
for (let q = 0; q < 96; q++) {
    let kwartierMs = startDagMs + (q * 15 * 60000);

    // De kwartier-prijs geldt voor de komende 15 minuten!
    let prijsEpexKwartier = dataMapEpex[kwartierMs] ?? null;
    let prijsOnb15Kwartier = dataMapOnb15[kwartierMs] ?? null;

    // Loop nu over de 15 minuten BINNEN dit kwartier
    for (let m = 0; m < 15; m++) {
        let minuutMs = kwartierMs + (m * 60000);
        let curD = new Date(minuutMs);

        let tijdStr = curD.getHours().toString().padStart(2, '0') + ":" + curD.getMinutes().toString().padStart(2, '0');
        let timestampVolledig = `${doelDatumStr} ${tijdStr}`;

        resultaat.push({
            tijdstip: timestampVolledig,
            prijs: prijsEpexKwartier,             // Altijd ingevuld voor het hele kwartier
            onbalans_kwartier: prijsOnb15Kwartier, // Altijd ingevuld voor het hele kwartier
            onbalans_minuut: dataMapOnb1[minuutMs] ?? null
        });
    }
}

node.status({ fill: "blue", shape: "dot", text: `${doelDatumStr}: ${resultaat.length} rijen` });
msg.payload = resultaat;
return msg;

let startDatum = (msg.req && msg.req.query && msg.req.query.start) 
                 ? msg.req.query.start 
                 : new Date(Date.now() - 7 * 86400000).toISOString().split('T')[0];
let eindDatum = (msg.req && msg.req.query && msg.req.query.eind) 
                ? msg.req.query.eind 
                : new Date().toISOString().split('T')[0];

node.status({ fill: "green", shape: "dot", text: `Raw dump: ${startDatum} tot ${eindDatum}` });

let dStart = new Date(startDatum + "T00:00:00Z");
dStart.setHours(dStart.getHours() - 3);
let dStop = new Date(eindDatum + "T23:59:59Z");
dStop.setHours(dStop.getHours() + 3);

msg.query = `
from(bucket: "energie_db")
  |> range(start: ${dStart.toISOString()}, stop: ${dStop.toISOString()})
  |> filter(fn: (r) => r["_measurement"] == "epex_kwartier" or r["_measurement"] == "onbalans_kwartier" or r["_measurement"] == "onbalans_minuut")
  |> filter(fn: (r) => r["_field"] == "prijs")
`;

return msg;

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.payload = [];
    return msg;
}

let startDatum = (msg.req && msg.req.query && msg.req.query.start) ? msg.req.query.start : null;
let eindDatum = (msg.req && msg.req.query && msg.req.query.eind) ? msg.req.query.eind : null;

// Eén efficiënte formatter voor Datum én Tijd in de Belgische tijdzone
const dtFormatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Brussels',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false
});

let buckets = {};

for (let i = 0; i < msg.payload.length; i++) {
    let row = msg.payload[i];
    if (!row._time) continue;

    // Converteert bliksemsnel naar formaat "YYYY-MM-DD HH:mm"
    let dtStr = dtFormatter.format(new Date(row._time));
    let localDate = dtStr.substring(0, 10);
    let tijdStr = dtStr.substring(11, 16);

    // BUGFIX: Zorg dat de +/- 3 uur marge niet overbloedt naar andere dagen!
    if (startDatum && localDate < startDatum) continue;
    if (eindDatum && localDate > eindDatum) continue;

    if (!buckets[tijdStr]) {
        buckets[tijdStr] = { epex: [], onb15: [], onb1: [] };
    }

    if (row._measurement === "epex_kwartier") buckets[tijdStr].epex.push(row._value);
    else if (row._measurement === "onbalans_kwartier") buckets[tijdStr].onb15.push(row._value);
    else if (row._measurement === "onbalans_minuut") buckets[tijdStr].onb1.push(row._value);
}

function avg(arr) {
    if (!arr || arr.length === 0) return null;
    let sum = 0;
    for (let i = 0; i < arr.length; i++) sum += arr[i];
    return sum / arr.length;
}

let resultaat = [];
let curEpexGem = null, curEpexMin = null, curEpexMax = null, curOnb15Gem = null;

for (let h = 0; h < 24; h++) {
    for (let m = 0; m < 60; m++) {
        let tijdStr = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
        let b = buckets[tijdStr] || { epex: [], onb15: [], onb1: [] };

        if (m % 15 === 0) {
            curEpexGem = avg(b.epex);
            curEpexMin = b.epex.length > 0 ? Math.min(...b.epex) : null;
            curEpexMax = b.epex.length > 0 ? Math.max(...b.epex) : null;
            curOnb15Gem = avg(b.onb15);
        }

        resultaat.push({
            tijdstip: tijdStr,
            epex_gem: curEpexGem,
            epex_min: curEpexMin,
            epex_max: curEpexMax,
            onb15_gem: curOnb15Gem,
            onb1_gem: avg(b.onb1)
        });
    }
}

msg.payload = resultaat;
return msg;

let jaar = (msg.req && msg.req.query && msg.req.query.jaar) ? parseInt(msg.req.query.jaar) : new Date().getFullYear();
let maand = (msg.req && msg.req.query && msg.req.query.maand) ? parseInt(msg.req.query.maand) : (new Date().getMonth() + 1);

// Maak een keiharde 'Prefix' string (bijv. "2026-10-") om later streng te filteren
let strJaar = String(jaar);
let strMaand = String(maand).padStart(2, '0');
let targetPrefix = `${strJaar}-${strMaand}-`;

let aantalDagen = new Date(jaar, maand, 0).getDate();

// Pak héél ruim (+- 4 uur) de UTC grenzen, we filteren de overloop er in de volgende stap toch uit!
let dStart = new Date(Date.UTC(jaar, maand - 1, 1, -4, 0, 0));
let dStop = new Date(Date.UTC(jaar, maand, 0, 27, 59, 59));

node.status({ fill: "green", shape: "dot", text: `${strMaand}-${strJaar} (${aantalDagen}d)` });

msg.query = `
from(bucket: "energie_db")
  |> range(start: ${dStart.toISOString()}, stop: ${dStop.toISOString()})
  |> filter(fn: (r) => r["_measurement"] == "epex_kwartier" or r["_measurement"] == "onbalans_kwartier" or r["_measurement"] == "onbalans_minuut")
  |> filter(fn: (r) => r["_field"] == "prijs")
`;

msg.targetPrefix = targetPrefix;
msg.aantalDagen = aantalDagen;
return msg;

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.payload = [];
    return msg;
}

const dtFormatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Brussels',
    year: 'numeric', month: '2-digit', day: '2-digit'
});

let buckets = {};

for (let i = 0; i < msg.payload.length; i++) {
    let row = msg.payload[i];
    if (!row._time) continue;

    let dtStr = dtFormatter.format(new Date(row._time));

    // DE BUGFIX: Als de datum NIET begint met "2026-10-", sla hem dan genadeloos over!
    if (!dtStr.startsWith(msg.targetPrefix)) continue;

    let dagNummer = parseInt(dtStr.split('-')[2], 10);

    if (!buckets[dagNummer]) {
        buckets[dagNummer] = { epex: [], onb15: [], onb1: [] };
    }

    if (row._measurement === "epex_kwartier") buckets[dagNummer].epex.push(row._value);
    else if (row._measurement === "onbalans_kwartier") buckets[dagNummer].onb15.push(row._value);
    else if (row._measurement === "onbalans_minuut") buckets[dagNummer].onb1.push(row._value);
}

function avg(arr) {
    if (!arr || arr.length === 0) return null;
    let sum = 0;
    for (let i = 0; i < arr.length; i++) sum += arr[i];
    return sum / arr.length;
}

let resultaat = [];

for (let d = 1; d <= msg.aantalDagen; d++) {
    let b = buckets[d] || { epex: [], onb15: [], onb1: [] };

    resultaat.push({
        dag: d,
        epex_gem: avg(b.epex),
        epex_min: b.epex.length > 0 ? Math.min(...b.epex) : null,
        epex_max: b.epex.length > 0 ? Math.max(...b.epex) : null,
        onb15_gem: avg(b.onb15),
        onb1_gem: avg(b.onb1)
    });
}

msg.payload = resultaat;
return msg;
